    'docs_dep_collection_desc' => 'जब एक नई लीज़ बनाई जाती है, तो सिस्टम आवश्यक सुरक्षा जमा को ट्रैक करता है। जमा भुगतान को तिथि, राशि, विधि और संदर्भ संख्या के साथ दर्ज करें।',
    'docs_dep_deductions' => 'जमा कटौती',
    'docs_dep_deductions_desc' => 'जब कोई किरायेदार बाहर जाता है, तो उनकी जमा राशि के विरुद्ध मदवार कटौती बनाएँ। प्रत्येक कटौती में एक विवरण और राशि शामिल होती है। कटौतियों को मूव-आउट निरीक्षण निष्कर्षों से जोड़ा जा सकता है।',
    'docs_dep_fee_type' => 'शुल्क प्रकार',
    'docs_dep_fee_type_desc' => 'किराए का प्रतिशत या निश्चित राशि',
    'docs_dep_fee_value' => 'शुल्क मूल्य',
    'docs_dep_fee_value_desc' => 'वसूलने के लिए प्रतिशत या निश्चित राशि',
    'docs_dep_forfeited' => 'क्षति/उल्लंघन के कारण पूरी जमा राशि रोक ली गई',
    'docs_dep_grace' => 'छूट अवधि',
    'docs_dep_grace_desc' => 'शुल्क लागू होने से पहले देय तिथि के बाद के दिनों की संख्या',
    'docs_dep_held' => 'सक्रिय किरायेदारी के दौरान जमा राशि रोक कर रखी जाती है',
    'docs_dep_intro' => 'अपनी प्रॉपर्टीज़ के लिए सुरक्षा जमा और विलंब शुल्क नियमों का प्रबंधन करें। पूरी किरायेदारी अवधि के दौरान जमा संग्रह, कटौतियों और रिफंड को ट्रैक करें।',
    'docs_dep_late_fees' => 'विलंब शुल्क कॉन्फ़िगरेशन',
    'docs_dep_late_fees_desc' => 'Settings में या प्रति-प्रॉपर्टी विलंब शुल्क कॉन्फ़िगर करें:',
    'docs_dep_max' => 'अधिकतम शुल्क',
    'docs_dep_max_desc' => 'कुल विलंब शुल्क पर सीमा (अत्यधिक शुल्क को रोकता है)',
    'docs_dep_partial' => 'कुछ राशि काटी गई, बाकी वापस की गई',
    'docs_dep_refund' => 'जमा रिफंड',
    'docs_dep_refund_desc' => 'कटौतियों के बाद, शेष जमा राशि किरायेदार को वापस कर दी जाती है। सिस्टम गणना करता है: रिफंड = जमा राशि − कुल कटौती। रिफंड की विधि और संदर्भ दर्ज करें।',
    'docs_dep_refunded' => 'पूरी जमा राशि किरायेदार को लौटाई गई',
    'docs_doc_cat1' => 'लीज़ अनुबंध',
