    'docs_doc_categories' => 'दस्तावेज़ श्रेणियाँ',
    'docs_doc_categories_desc' => 'दस्तावेज़ों को श्रेणी के अनुसार व्यवस्थित करें:',
    'docs_doc_intro' => 'प्रॉपर्टीज़, किरायेदारों और लीज़ से संबंधित दस्तावेज़ संग्रहीत और व्यवस्थित करें। अनुबंध, पहचान पत्र की प्रतियाँ, प्रमाणपत्र और अन्य महत्वपूर्ण फ़ाइलें अपलोड करें।',
    'docs_doc_linking' => 'एंटिटी लिंकिंग',
    'docs_doc_linking_desc' => 'आसान पुनर्प्राप्ति के लिए दस्तावेज़ों को विशिष्ट प्रॉपर्टीज़, यूनिट्स या किरायेदारों से जोड़ें। किसी किरायेदार की प्रोफ़ाइल देखते समय, आप उनके सभी संबंधित दस्तावेज़ देख सकते हैं।',
    'docs_doc_storage' => 'संग्रहण कोटा',
    'docs_doc_storage_desc' => 'प्रत्येक किरायेदार इंस्टेंस के पास उनके सब्सक्रिप्शन टियर के आधार पर एक संग्रहण कोटा होता है। दस्तावेज़ पृष्ठ से उपयोग की निगरानी करें। प्रति अपलोड अधिकतम फ़ाइल आकार: 10MB।',
    'docs_doc_upload' => 'दस्तावेज़ अपलोड करना',
    'docs_doc_upload_desc' => 'फ़ाइलें खींचें और छोड़ें या चुनने के लिए क्लिक करें। एक साथ कई फ़ाइलें अपलोड करें। समर्थित प्रारूप: PDF, DOC, DOCX, XLSX, CSV और छवियाँ।',
    'docs_exp_cat1' => 'मरम्मत और रखरखाव',
    'docs_exp_cat2' => 'कर और बीमा',
    'docs_exp_cat3' => 'स्टाफ और प्रबंधन शुल्क',
    'docs_exp_cat4' => 'उपयोगिताएँ (मकान मालिक द्वारा भुगतान)',
    'docs_exp_cat5' => 'अन्य / कस्टम श्रेणियाँ',
    'docs_exp_categories' => 'व्यय श्रेणियाँ',
    'docs_exp_categories_desc' => 'व्यय को श्रेणी के अनुसार व्यवस्थित करें:',
    'docs_exp_income_expense' => 'आय बनाम व्यय',
    'docs_exp_income_expense_desc' => 'किसी भी अवधि के लिए किराये की आय की व्यय से तुलना करें',
    'docs_exp_intro' => 'प्रॉपर्टी व्यय को ट्रैक करें, लाभ/हानि विवरण बनाएँ, और अपने पोर्टफोलियो की पूरी वित्तीय तस्वीर प्राप्त करें।',
    'docs_exp_pnl' => 'प्रति प्रॉपर्टी लाभ/हानि',
    'docs_exp_pnl_desc' => 'प्रत्येक प्रॉपर्टी के लिए शुद्ध आय देखें (मासिक, त्रैमासिक या वार्षिक)',
    'docs_exp_rec1' => '<strong>Expenses</strong> पर जाएँ और <strong>Add Expense</strong> पर क्लिक करें',
    'docs_exp_rec2' => 'प्रॉपर्टी चुनें (और वैकल्पिक रूप से एक विशिष्ट यूनिट)',
    'docs_exp_rec3' => 'श्रेणी चुनें, राशि, तिथि और विक्रेता दर्ज करें',
    'docs_exp_rec4' => 'रिकॉर्ड रखने के लिए रसीद की छवि अपलोड करें',
    'docs_exp_recording' => 'व्यय दर्ज करना',
    'docs_exp_reports' => 'वित्तीय रिपोर्ट',
    'docs_exp_void' => 'व्यय रद्दीकरण',
    'docs_exp_void_desc' => 'गलत व्यय को ऑडिट ट्रेल में रखते हुए रद्द करें',
    'docs_faq_a1' => 'लॉग इन करने के बाद, अपनी पहली प्रॉपर्टी जोड़ें, उसमें यूनिट्स बनाएँ, किरायेदारों को पंजीकृत करें, लीज़ बनाएँ, और भुगतान दर्ज करना शुरू करें। चरण-दर-चरण निर्देशों के लिए Getting Started गाइड का पालन करें।',
    'docs_faq_a10' => 'हमारी सहायता टीम से WhatsApp या ईमेल के माध्यम से संपर्क करें। Enterprise टियर सब्सक्राइबर्स को तेज़ प्रतिक्रिया समय के साथ प्राथमिकता सहायता मिलती है।',
    'docs_faq_a2' => 'हाँ! FIS Real Estate एक Progressive Web App (PWA) है। इसे अपने डिवाइस पर इंस्टॉल करें और ऑफ़लाइन काम करना जारी रखें। जब आप इंटरनेट से पुनः कनेक्ट होंगे तो आपके परिवर्तन स्वतः सिंक हो जाएँगे।',
    'docs_faq_a3' => 'आपसे मासिक बिल लिया जाता है जो आपके द्वारा प्रबंधित यूनिट्स की संख्या को आपके टियर दर से गुणा करके निर्धारित होता है। Basic %1$s TZS/यूनिट/माह है, Professional %2$s है, और Enterprise %3$s है। छूट लागू हो सकती है।',
    'docs_faq_a4' => 'टियर अपग्रेड का अनुरोध करने के लिए FIS Real Estate सहायता टीम से WhatsApp या ईमेल के माध्यम से संपर्क करें। आपका सब्सक्रिप्शन अपडेट कर दिया जाएगा और आपको तुरंत नई सुविधाओं तक पहुँच मिल जाएगी।',
    'docs_faq_a5' => 'हाँ, Professional टियर या उससे ऊपर के साथ। Tenant Portal किरायेदारों को लॉग इन करने, अपना बैलेंस, भुगतान इतिहास और लीज़ विवरण देखने की अनुमति देता है। आप प्रति किरायेदार पोर्टल एक्सेस सक्षम/अक्षम कर सकते हैं।',
    'docs_faq_a6' => 'विलंब शुल्क की गणना आपके कॉन्फ़िगरेशन के आधार पर स्वचालित रूप से की जाती है। आप शुल्क प्रकार (प्रतिशत या निश्चित), छूट अवधि और अधिकतम सीमा निर्धारित करते हैं। शुल्क तब लागू होते हैं जब देय तिथि और छूट अवधि तक किराया नहीं चुकाया जाता।',
    'docs_faq_a7' => 'हाँ, आप बिना किसी अतिरिक्त लागत के असीमित प्रॉपर्टीज़ का प्रबंधन कर सकते हैं। प्रत्येक प्रॉपर्टी की अपनी सेटिंग्स, यूनिट्स और किरायेदार हो सकते हैं। डैशबोर्ड आपकी सभी प्रॉपर्टीज़ का डेटा एकत्रित करता है।',
    'docs_faq_a8' => 'सिस्टम अंग्रेज़ी, स्वाहिली (Kiswahili), और अरबी (दाएँ-से-बाएँ लेआउट के साथ) का समर्थन करता है। शीर्ष बार में ग्लोब आइकन का उपयोग करके किसी भी समय भाषाएँ बदलें।',
    'docs_faq_a9' => 'अधिकांश सूची दृश्यों और रिपोर्ट में एक Export/CSV बटन होता है। डेटा को CSV फ़ाइल के रूप में डाउनलोड करने के लिए इस पर क्लिक करें जो Excel या Google Sheets में खुलती है। एडमिन Backup पृष्ठ से पूर्ण डेटाबेस बैकअप भी बना सकते हैं।',
    'docs_faq_intro' => 'FIS Real Estate के बारे में अक्सर पूछे जाने वाले प्रश्न।',
    'docs_faq_q1' => 'मैं सिस्टम का उपयोग कैसे शुरू करूँ?',
