    'docs_gs_add_property' => 'प्रॉपर्टी जोड़ें',
    'docs_gs_add_property_desc' => 'Properties पर जाएँ और पता और प्रकार के साथ अपनी पहली प्रॉपर्टी बनाएँ।',
    'docs_gs_add_tenants' => 'किरायेदार पंजीकृत करें',
    'docs_gs_add_tenants_desc' => 'संपर्क जानकारी, पहचान पत्र की प्रतियों और स्क्रीनिंग विवरण के साथ किरायेदार प्रोफ़ाइल जोड़ें।',
    'docs_gs_add_units' => 'यूनिट्स जोड़ें',
    'docs_gs_add_units_desc' => 'प्रॉपर्टी के भीतर यूनिट्स बनाएँ — अपार्टमेंट, कमरे, दुकानें, आदि। किराया राशि निर्धारित करें।',
