    'docs_gs_create_leases' => 'लीज़ बनाएँ',
    'docs_gs_create_leases_desc' => 'लीज़ अनुबंधों के साथ किरायेदारों को यूनिट्स से जोड़ें। किराया, तिथियाँ और भुगतान आवृत्ति निर्धारित करें।',
    'docs_gs_description' => 'विवरण',
    'docs_gs_ent_desc' => 'पूर्ण सुइट: उपयोगिताएँ, रखरखाव, व्यय, गेटवे',
    'docs_gs_first_login' => 'पहला लॉगिन',
    'docs_gs_first_login_desc' => 'आपका खाता प्रावधानित होने के बाद, आपको ईमेल या WhatsApp के माध्यम से लॉगिन क्रेडेंशियल प्राप्त होंगे। उनका उपयोग अपने किरायेदार URL पर साइन इन करने के लिए करें।',
    'docs_gs_help' => 'मदद चाहिए? WhatsApp या ईमेल के माध्यम से सहायता से संपर्क करें। सामान्य प्रश्नों के लिए FAQ अनुभाग देखें।',
    'docs_gs_intro' => 'FIS Real Estate में आपका स्वागत है — तंज़ानिया और उससे परे मकान मालिकों और प्रॉपर्टी प्रबंधकों के लिए डिज़ाइन की गई एक व्यापक प्रॉपर्टी प्रबंधन प्रणाली।',
    'docs_gs_languages' => 'भाषा समर्थन',
    'docs_gs_languages_desc' => 'सिस्टम अंग्रेज़ी, स्वाहिली (Kiswahili), और अरबी (दाएँ-से-बाएँ लेआउट के साथ) का समर्थन करता है। शीर्ष बार में ग्लोब आइकन का उपयोग करके भाषाएँ बदलें।',
    'docs_gs_offline' => 'ऑफ़लाइन और PWA समर्थन',
    'docs_gs_offline_desc' => 'FIS Real Estate एक Progressive Web App (PWA) के रूप में ऑफ़लाइन काम करता है। आप इसे अपने डिवाइस पर इंस्टॉल कर सकते हैं और इंटरनेट के बिना भी काम करना जारी रख सकते हैं। पुनः कनेक्ट होने पर परिवर्तन स्वतः सिंक हो जाते हैं।',
    'docs_gs_pro_desc' => 'किरायेदार पोर्टल, रिमाइंडर, दस्तावेज़ प्रबंधन',
    'docs_gs_quick_setup' => 'त्वरित सेटअप चेकलिस्ट',
