    'docs_vid_coming' => 'वीडियो ट्यूटोरियल तैयार किए जा रहे हैं। नीचे प्लेसहोल्डर एम्बेड दिखाए गए हैं। नए वीडियो के लिए फिर से जाँचें।',
    'docs_vid_coming_soon' => 'जल्द आ रहा है',
    'docs_vid_intro' => 'FIS Real Estate का प्रभावी ढंग से उपयोग करना सीखने के लिए चरण-दर-चरण वीडियो ट्यूटोरियल देखें।',
    'docs_vid_request' => 'किसी विशिष्ट विषय पर ट्यूटोरियल चाहिए? हमारी सहायता टीम से संपर्क करें और हम आपके लिए एक बना देंगे।',
    'docs_vid_t10_desc' => 'किरायेदार बैलेंस, भुगतान देखने और अपनी प्रोफ़ाइल प्रबंधित करने के लिए स्व-सेवा पोर्टल का उपयोग कैसे करते हैं।',
    'docs_vid_t10_title' => 'Tenant Portal वॉकथ्रू',
    'docs_vid_t11_desc' => 'ऐप को अपने डिवाइस पर इंस्टॉल करें, ऑफ़लाइन काम करें, और वापस ऑनलाइन आने पर सिंक करें।',
    'docs_vid_t11_title' => 'PWA और ऑफ़लाइन मोड',
    'docs_vid_t12_desc' => 'मोबाइल मनी गेटवे कॉन्फ़िगर करें, भुगतान परीक्षण करें, और लेनदेन समाधान का प्रबंधन करें।',
    'docs_vid_t12_title' => 'Payment Gateway सेटअप',
    'docs_vid_t1_desc' => 'FIS Real Estate सिस्टम का एक संपूर्ण वॉकथ्रू, जिसमें लॉगिन, नेविगेशन और प्रमुख सुविधाएँ शामिल हैं।',
    'docs_vid_t1_title' => 'शुरुआत करना — सिस्टम अवलोकन',
    'docs_vid_t2_desc' => 'प्रॉपर्टीज़ बनाना, यूनिट्स जोड़ना, किराया राशि निर्धारित करना और फ़ोटो अपलोड करना सीखें।',
    'docs_vid_t2_title' => 'प्रॉपर्टीज़ और यूनिट्स जोड़ना',
    'docs_vid_t3_desc' => 'किरायेदारों को कैसे पंजीकृत करें, लीज़ बनाएँ, नवीनीकरण अलर्ट सेट करें, और समाप्ति को संभालें।',
    'docs_vid_t3_title' => 'किरायेदारों और लीज़ का प्रबंधन',
    'docs_vid_t4_desc' => 'भुगतान दर्ज करें, रसीदें बनाएँ, थोक भुगतान संभालें, और भुगतान उलटने का प्रबंधन करें।',
    'docs_vid_t4_title' => 'भुगतान और रसीदें दर्ज करना',
    'docs_vid_t5_desc' => 'सुरक्षा जमा को ट्रैक करें, कटौतियाँ बनाएँ, रिफंड प्रोसेस करें, और विलंब शुल्क नियम कॉन्फ़िगर करें।',
    'docs_vid_t5_title' => 'जमा और विलंब शुल्क',
    'docs_vid_t6_desc' => 'चेकलिस्ट के साथ निरीक्षण करें, फ़ोटो अपलोड करें, और तुलना रिपोर्ट बनाएँ।',
    'docs_vid_t6_title' => 'मूव-इन/मूव-आउट निरीक्षण',
    'docs_vid_t7_desc' => 'डैशबोर्ड नेविगेट करें, वित्तीय रिपोर्ट बनाएँ, और डेटा को CSV के रूप में निर्यात करें।',
