    'docs_vid_t8_desc' => 'सिस्टम सेटिंग्स कॉन्फ़िगर करें, उपयोगकर्ताओं का प्रबंधन करें, विस्तृत अनुमतियों के साथ कस्टम भूमिकाएँ बनाएँ।',
