    // Page introductions (part 35)
    'intro_next' => 'आगे:',
    'intro_hide' => 'छिपाएँ',
    'intro_show' => 'यह पृष्ठ क्या है?',
    'intro_go_units' => 'इकाइयाँ जोड़ें',
    'intro_go_unit_new' => 'इकाई जोड़ें',
    'intro_go_tenants' => 'किरायेदार दर्ज करें',
    'intro_go_tenant_new' => 'किरायेदार जोड़ें',
    'intro_go_lease_new' => 'पट्टा बनाएँ',
    'intro_go_payments' => 'भुगतान',
    'intro_go_payment_new' => 'भुगतान दर्ज करें',
    'intro_go_deposit_new' => 'जमा दर्ज करें',
    'intro_go_charges' => 'बकाया देखें',
    'intro_go_floats' => 'नकद बैंक में जमा करें',
    'intro_go_payables' => 'अनुमोदन',
    'intro_go_mappings' => 'खाता मानचित्रण',
    'intro_go_statements' => 'वित्तीय विवरण',
    'intro_go_journal' => 'रोजनामचा',
    'intro_go_tb' => 'तलपट',
    'intro_go_aged' => 'बकाया आयु',
    'intro_properties_index_what' => 'आपके द्वारा प्रबंधित हर भवन। संपत्ति में इकाइयाँ होती हैं, और बाकी सब — किरायेदार, पट्टे, किराया — उन्हीं इकाइयों पर आधारित है।',
    'intro_properties_index_how' => 'नए सिस्टम में यहीं से शुरू करें। संपत्ति जोड़ें, फिर उसकी इकाइयाँ जोड़ें। इकाइयाँ, फ़ोटो और खर्च देखने के लिए किसी भी संपत्ति पर क्लिक करें।',
    'intro_properties_create_what' => 'भवन जोड़ें। केवल नाम आवश्यक है — बाकी बाद में भरा जा सकता है।',
    'intro_properties_create_how' => 'ऐसा नाम दें जिसे लोग रिपोर्ट में पहचान सकें। सहेजने के बाद इकाइयाँ जोड़ें।',
    'intro_properties_view_what' => 'एक संपत्ति के बारे में सब कुछ: इकाइयाँ, कितनी भरी हैं, फ़ोटो और लागत।',
    'intro_properties_view_how' => 'इकाइयों, फ़ोटो और खर्च के बीच जाने के लिए टैब का उपयोग करें। पट्टे शुरू और समाप्त होने पर अधिभोग स्वयं अपडेट होता है।',
    'intro_units_index_what' => 'आपकी संपत्तियों में हर किराए योग्य स्थान, उसके किराए और अधिभोग के साथ।',
    'intro_units_index_how' => 'पट्टा बनाते ही इकाई स्वतः भरी हो जाती है, और पट्टा समाप्त होने पर खाली। किराया यहाँ सेट करें — नए पट्टे इसे डिफ़ॉल्ट के रूप में लेते हैं।',
    'intro_units_create_what' => 'संपत्ति में किराए योग्य स्थान जोड़ें — फ्लैट, कमरा, दुकान या कार्यालय।',
    'intro_units_create_how' => 'यहाँ सेट किया किराया और मुद्रा इस इकाई पर पट्टा बनाते समय डिफ़ॉल्ट बनते हैं। स्थिति खाली रहने दें; पट्टा शुरू होते ही यह स्वयं बदल जाती है।',
    'intro_units_view_what' => 'एक इकाई: उसका वर्तमान पट्टा, किराया, फ़ोटो और इतिहास।',
    'intro_units_view_how' => 'यदि इकाई भरी दिख रही है पर कोई पट्टा नहीं है, तो पुराना पट्टा बिना मुक्त किए हटाया गया — इकाई की स्थिति संपादित कर ठीक करें।',
    'intro_tenants_index_what' => 'आपसे किराए पर लेने वाले सभी, पूर्व और वर्तमान।',
    'intro_tenants_index_how' => 'पट्टे पर रखने से पहले किरायेदार दर्ज करें। पट्टे, भुगतान, दस्तावेज़ और पहचान पत्र देखने के लिए नाम पर क्लिक करें।',
    'intro_tenants_create_what' => 'किसी को दर्ज करें ताकि उसे पट्टे पर रखा जा सके।',
    'intro_tenants_create_how' => 'केवल नाम और फ़ोन आवश्यक हैं। TIN, निकटतम परिजन और रोजगार अभी या बाद में जोड़ें — पहचान पत्र सहेजने के बाद किरायेदार पृष्ठ से अपलोड होता है।',
    'intro_tenants_view_what' => 'एक किरायेदार: उसके पट्टे, भुगतान, बकाया, दस्तावेज़ और पहचान।',
    'intro_tenants_view_how' => 'दाईं ओर आईडी दस्तावेज़ कार्ड में पहचान पत्र अपलोड करें। बाकी सब — अनुबंध, पत्राचार, संदर्भ — के लिए दस्तावेज़ टैब का उपयोग करें।',
    'intro_tenants_edit_what' => 'किरायेदार का विवरण बदलें।',
    'intro_tenants_edit_how' => 'पहचान पत्र यहाँ नहीं है — यह किरायेदार के अपने पृष्ठ से प्रबंधित होता है, क्योंकि यह फ़ाइल है, फ़ील्ड नहीं।',
    'intro_leases_index_what' => 'किरायेदार को इकाई से जोड़ने वाला हर अनुबंध, उसके किराए, अवधि और भुगतान आवृत्ति के साथ।',
    'intro_leases_index_how' => 'पट्टा ही किराया वसूली शुरू करता है। जब तक इकाई पर सक्रिय पट्टा नहीं, न बिल बनता है न बकाया दिखता है।',
    'intro_leases_create_what' => 'सहमत शर्तों पर किरायेदार को इकाई में रखें।',
    'intro_leases_create_how' => 'सूची में केवल खाली या आरक्षित इकाइयाँ दिखती हैं — कोई इकाई गायब है तो वह पुराने पट्टे से भरी चिह्नित है। किराया और जमा इकाई से भरते हैं, और भुगतान आवृत्ति तय करती है कि किराया कितनी बार लगेगा।',
    'intro_leases_view_what' => 'एक पट्टा: उसकी शर्तें, उसके विरुद्ध भुगतान, और दस्तावेज़।',
    'intro_leases_view_how' => 'आरंभ तिथि से हर अवधि में किराया स्वतः लगता है। हस्ताक्षर योग्य अनुबंध के लिए प्रिंट का उपयोग करें।',

    // Page introductions, money and ledger pages (part 35b)
    'intro_payments_index_what' => 'प्राप्त हर भुगतान, और उनके लिए जारी रसीदें।',
    'intro_payments_index_how' => 'भुगतान पहले सबसे पुराने बकाया शुल्क चुकाता है। आंशिक भुगतान पर शेष बकाया रहता है — आंशिक भुगतान को शून्य नहीं माना जाता।',
    'intro_payments_create_what' => 'किरायेदार से प्राप्त धन दर्ज करें।',
    'intro_payments_create_how' => 'भुगतान का तरीका चुनें: नकद और चेक बैंक में जमा करने तक आपके पास रहते हैं, जबकि बैंक ट्रांसफर सीधे बैंक जाते हैं। राशि स्वतः सबसे पुराने बकाया पर लगती है।',
    'intro_payments_view_what' => 'एक भुगतान: उसने क्या चुकाया, उसकी रसीद, और संलग्न दस्तावेज़।',
    'intro_payments_view_how' => 'भुगतान प्रतिवर्तित करने पर वे शुल्क फिर खुल जाते हैं, और किरायेदार का बकाया पहले जैसा हो जाता है।',
    'intro_deposits_index_what' => 'आपके पास रखी सुरक्षा जमा, और उनका क्या हुआ।',
    'intro_deposits_index_how' => 'जमा किरायेदार का धन है जब तक वह जब्त न हो, इसलिए यह अर्जित नहीं, रखा हुआ है। वापसी या जब्ती के लिए दूसरे व्यक्ति की स्वीकृति चाहिए।',
    'intro_deposits_create_what' => 'पट्टे के विरुद्ध प्राप्त जमा दर्ज करें।',
    'intro_deposits_create_how' => 'नकद किराए के भुगतान की तरह ही आपके पास आता है। जमा को किरायेदार के लिए रखा धन दर्ज किया जाता है, आय नहीं।',
    'intro_deposits_view_what' => 'एक जमा: कितना रखा है, कटौतियाँ, और वापसी की स्थिति।',
    'intro_deposits_view_how' => 'वापसी से पहले कटौतियाँ मदवार दर्ज करें। वापसी और जब्ती तुरंत नहीं होतीं, अनुरोध बनाती हैं — कोई और बही, देय के अंतर्गत स्वीकृत करता है।',
    'intro_expenses_index_what' => 'संपत्तियाँ चलाने पर आपका खर्च — बिजली, वेतन, मरम्मत।',
    'intro_expenses_index_how' => 'बिल आते ही दर्ज करें, चाहे भुगतान हुआ हो या नहीं। लागत उसी माह में गिनी जाती है जिसमें हुई, और भुगतान स्वीकृत होने तक देय रहती है।',
    'intro_ledger_index_what' => 'आपकी खाता सूची — बैंक खाते, नकदी बॉक्स, और आय-व्यय श्रेणियाँ जिनके विरुद्ध सब दर्ज होता है।',
    'intro_ledger_index_how' => 'भुगतान दर्ज करने से पहले यह सेट करें। बैंक खाते जोड़ें, फिर डिफ़ॉल्ट बैंक मैप करें ताकि ट्रांसफर को गंतव्य पता हो। सिस्टम चिह्नित खाते स्वतः बनते हैं और हटाए नहीं जा सकते।',
    'intro_ledger_mappings_what' => 'स्वचालित प्रविष्टियाँ कहाँ जाती हैं। हर घटना — किराया, जमा, बैंक ट्रांसफर — एक खाते की ओर संकेत करती है।',
    'intro_ledger_mappings_how' => 'हाइलाइट पंक्तियाँ अभी मैप नहीं हैं और उन घटनाओं के दर्ज होने से पहले सेट होनी चाहिए। नीचे बही बंद करने से उस तिथि या पहले कुछ भी दर्ज नहीं होता।',
    'intro_ledger_charges_what' => 'किरायेदारों का बकाया: देय होने पर किराया, उपयोगिताएँ और विलंब शुल्क।',
    'intro_ledger_charges_how' => 'हर सक्रिय पट्टे के लिए प्रत्येक अवधि में शुल्क स्वतः बनते हैं। यदि यह खाली है, तो दैनिक जेनरेटर अभी नहीं चला — शुल्क बने बिना कोई बकाया नहीं।',
    'intro_ledger_floats_what' => 'आपके लोगों के पास कंपनी की ओर से रखा नकद, और उनके घोषित जमा।',
    'intro_ledger_floats_how' => 'जब कोई पहली बार नकद भुगतान दर्ज करता है, नकद शेष स्वयं बन जाता है। धन बैंक पहुँचने पर बैंक में जमा करें का उपयोग करें — दूसरे व्यक्ति की स्वीकृति पर ही शेष घटता है।',
    'intro_ledger_payables_what' => 'भुगतान या स्वीकृति की प्रतीक्षा में सब कुछ: आपूर्तिकर्ता बिल, और सहकर्मी द्वारा माँगी गई जमा वापसी।',
    'intro_ledger_payables_how' => 'स्वीकृति से ही धन वास्तव में बाहर जाता है। आप अपना अनुरोध स्वीकृत नहीं कर सकते, इसलिए कम से कम दो लोगों को अनुमोदन अधिकार चाहिए।',
    'intro_ledger_journal_what' => 'बही में हर प्रविष्टि, चाहे व्यक्ति ने दर्ज की हो या सिस्टम ने।',
    'intro_ledger_journal_how' => 'स्वीकृति की प्रतीक्षा में प्रविष्टियाँ कुछ प्रभावित नहीं करतीं। पोस्ट की गई प्रविष्टियाँ कभी संपादित नहीं होतीं — गलती को प्रतिवर्तित कर सुधारें, दोनों रिकॉर्ड पर रहती हैं।',
    'intro_ledger_create_what' => 'हाथ से वह दर्ज करें जो सिस्टम स्वयं नहीं निकाल सकता — प्रारंभिक शेष, सुधार, या समायोजन।',
    'intro_ledger_create_how' => 'जमा करने से पहले नामे और जमा बराबर होने चाहिए, और हर पंक्ति एक ही मुद्रा का खाता प्रयोग करे। फिर कोई और स्वीकृत करता है।',
    'intro_ledger_view_what' => 'एक प्रविष्टि, उसकी पंक्तियाँ, और किसने बनाई व स्वीकृत की।',
    'intro_ledger_view_how' => 'पोस्ट की गई प्रविष्टि संपादित या हटाई नहीं जा सकती। दर्पण प्रविष्टि से रद्द करने के लिए प्रतिवर्तित करें — मूल दिखती रहती है, प्रतिवर्तित चिह्नित।',
    'intro_ledger_trial-balance_what' => 'स्वास्थ्य जाँच: कुल नामे बनाम कुल जमा, प्रति मुद्रा।',
    'intro_ledger_trial-balance_how' => 'ये बराबर होने चाहिए। हर प्रविष्टि सहेजते समय जाँची जाती है, तो अंतर होने पर कुछ ने एप्लिकेशन के बाहर डेटाबेस बदला है।',
    'intro_ledger_statements_what' => 'लाभ-हानि, तुलन-पत्र, इकाईवार लाभप्रदता, और कौन भुगतान में पीछे है।',
    'intro_ledger_statements_how' => 'हर आँकड़ा एक लिंक है — खाते तक, फिर उसके पीछे की प्रविष्टियों तक क्लिक करें। आय देय होने पर और व्यय होने पर गिने जाते हैं, नकद चलने पर नहीं।',
    'intro_ledger_account_what' => 'एक खाते पर हर गतिविधि, चालू शेष के साथ।',
    'intro_ledger_account_how' => 'यहीं विवरण का आँकड़ा समझाया जाता है। हर प्रविष्टि संख्या उस पूरी प्रविष्टि से जुड़ती है जहाँ से वह आई।',

    // Page introduction links (part 35c)
    'intro_go_deposits' => 'जमा',
    'intro_go_deductions' => 'कटौतियाँ',
    'intro_go_expenses' => 'व्यय',
    'intro_go_inquiries' => 'पूछताछ',
    'intro_go_users' => 'उपयोगकर्ता',
    // Page introductions — batch 2 (part 35d)
    'intro_properties_edit_what' => 'किसी संपत्ति का विवरण बदलें।',
    'intro_properties_edit_how' => 'नाम बदलने से हर रिपोर्ट और विवरण में उसका नाम बदल जाता है, पुरानी रिपोर्टों में भी।',
    'intro_properties_photos_what' => 'भवन की तस्वीरें — खाली इकाइयों के विज्ञापन और स्थिति के रिकॉर्ड के लिए उपयोगी।',
    'intro_properties_photos_how' => 'यहाँ की तस्वीरें पूरी संपत्ति दिखाती हैं। किसी एक फ़्लैट की तस्वीरें उसी इकाई पर लगाएँ।',
    'intro_properties_settings_what' => 'केवल इसी संपत्ति पर लागू नियम, जैसे इसका किराया चक्र और विलंब शुल्क की शर्तें।',
    'intro_properties_settings_how' => 'यहाँ जो भी तय किया जाए वह केवल इस संपत्ति के लिए सिस्टम की सामान्य सेटिंग को हटा देता है। सामान्य नियम पर बने रहने के लिए फ़ील्ड खाली छोड़ें।',
    'intro_units_edit_what' => 'इकाई का विवरण या उसका किराया बदलें।',
    'intro_units_edit_how' => 'किराया बदलने से मौजूदा पट्टे नहीं बदलते — उनमें हस्ताक्षर के समय तय रकम बनी रहती है। जो वसूला जाता है उसे बदलने के लिए पट्टे में ही किराया बदलें।',
    'intro_units_photos_what' => 'इस इकाई की तस्वीरें, विज्ञापन और स्थिति के रिकॉर्ड के लिए।',
    'intro_units_photos_how' => 'ये प्रवेश और निकास के समय लें; जमा को लेकर होने वाले अधिकांश विवाद शुरू होने से पहले ही निपट जाते हैं।',
    'intro_leases_edit_what' => 'मौजूदा पट्टे की शर्तें बदलें।',
    'intro_leases_edit_how' => 'किराया या आवृत्ति बदलने का असर अब से बनने वाले शुल्कों पर पड़ता है। पहले बन चुके शुल्क अपनी मूल रकम रखते हैं — ग़लत हों तो उन्हें उलटें।',
    'intro_leases_templates_what' => 'पट्टा अनुबंध छापते समय इस्तेमाल होने वाला मसौदा।',
    'intro_leases_templates_how' => '{{rent_amount}} जैसे प्लेसहोल्डर छपाई के समय पट्टे से भर दिए जाते हैं। किसी एक को डिफ़ॉल्ट बनाएँ, नए पट्टे उसी का उपयोग करेंगे।',
    'intro_deposits_edit_what' => 'पहले से दर्ज जमा का विवरण सुधारें।',
    'intro_deposits_edit_how' => 'वापसी और ज़ब्ती यहाँ नहीं होती — वे जमा के अपने पन्ने से माँगी जाती हैं और उन्हें स्वीकृति चाहिए।',
    'intro_payments_edit_what' => 'पहले से दर्ज भुगतान का विवरण सुधारें।',
    'intro_payments_edit_how' => 'भुगतान पूरी तरह रद्द करने के लिए उसे उसके अपने पन्ने से उलटें — इससे वे शुल्क फिर खुल जाते हैं जो उसने चुकाए थे और खातों से भी वह हट जाता है।',
    'intro_payments_bulk_what' => 'एक साथ कई भुगतान दर्ज करें, जब किराए के दिन कतार लग जाए।',
    'intro_payments_bulk_how' => 'हर पंक्ति उस किरायेदार के सबसे पुराने बकाया शुल्कों पर लगती है, ठीक वैसे ही जैसे कोई अकेला भुगतान लगता।',
    'intro_deposits_late-fees_what' => 'किराया समय पर न चुकाने पर जोड़ा गया शुल्क।',
    'intro_deposits_late-fees_how' => 'ये आपके विलंब शुल्क नियमों के अनुसार रोज़ चलने वाली प्रक्रिया से अपने आप लगते हैं। शुल्क कारण दर्ज करके माफ़ किया जा सकता है।',
    'intro_deposits_late-fee-settings_what' => 'ये नियम तय करते हैं कि विलंब शुल्क कब लगेगा और कितना होगा।',
    'intro_deposits_late-fee-settings_how' => 'छूट अवधि रखें ताकि एक दिन देर से आया भुगतान दंडित न हो, और अधिकतम सीमा रखें ताकि लंबे बकाया खाते पर शुल्क बेकाबू न हों।',
    'intro_documents_index_what' => 'सिस्टम में रखी हर फ़ाइल, और हर एक किससे जुड़ी है।',
    'intro_documents_index_how' => 'श्रेणी से या दस्तावेज़ जिससे जुड़ा है उससे छाँटें। गोपनीय चिह्नित फ़ाइलों पर निशान लगता है, पर वे इस पन्ने को खोल सकने वाले हर व्यक्ति को दिखती हैं।',
    'intro_documents_upload_what' => 'फ़ाइल जोड़ें और उसे संपत्ति, इकाई, किरायेदार, पट्टे, भुगतान, जमा या व्यय से जोड़ें।',
    'intro_documents_upload_how' => 'किसी रिकॉर्ड से यहाँ आने पर वही पहले से चुना मिलता है, और सही जगह फ़ाइल रखने का यही सबसे पक्का तरीका है।',
    'intro_documents_view_what' => 'एक दस्तावेज़: जहाँ संभव हो पूर्वावलोकन, और वह किससे जुड़ा है।',
    'intro_documents_view_how' => 'जो ब्राउज़र न दिखा सके उसके लिए डाउनलोड का उपयोग करें। संपादन रिकॉर्ड बदलता है, फ़ाइल नहीं — फ़ाइल बदलने के लिए फिर से अपलोड करें।',
    'intro_inspections_index_what' => 'इकाइयों की स्थिति की जाँच — प्रवेश, निकास या नियमित।',
    'intro_inspections_index_how' => 'निकास जाँच ही जमा से कटौती को उचित ठहराती है, इसलिए कोई भी जमा लौटाने से पहले यह कर लें।',
    'intro_inspections_create_what' => 'किसी इकाई की स्थिति की जाँच शुरू करें।',
    'intro_inspections_create_how' => 'तैयार सूची पाने के लिए कोई टेम्पलेट चुनें। जिस भी चीज़ का बाद में पैसा माँग सकते हैं उसकी तस्वीर लें।',
    'intro_inspections_view_what' => 'एक जाँच: हर जाँचा गया मद, उसकी स्थिति और उसकी तस्वीरें।',
    'intro_inspections_view_how' => 'क्षतिग्रस्त चिह्नित मदों को जमा की कटौती में बदला जा सकता है, उनके विवरण और तस्वीरों सहित।',
    'intro_inspections_move-out_what' => 'किरायेदार के जाने पर होने वाली जाँच, जिसमें इकाई की तुलना उस हालत से की जाती है जिसमें उसने पाई थी।',
    'intro_inspections_move-out_how' => 'जमा लौटाने से पहले इसे पूरा करें — इसके बिना की गई कटौतियों का बचाव कठिन होता है।',
    'intro_inspections_deductions_what' => 'क्षति या सफ़ाई के बदले जमा से रोकी गई रकम।',
    'intro_inspections_deductions_how' => 'हर कटौती किसी जाँच में मिली बात पर टिकी होनी चाहिए। कटौतियों के बाद जो बचता है वही लौटाया जाता है।',
    'intro_inspections_templates_what' => 'दोबारा इस्तेमाल होने वाली सूचियाँ, ताकि हर जाँच में वही बातें देखी जाएँ।',
    'intro_inspections_templates_how' => 'हर तरह की संपत्ति के लिए एक बनाएँ। एक जैसी सूची ही दो जाँचों की तुलना संभव बनाती है।',
    'intro_maintenance_index_what' => 'मरम्मत और रखरखाव के अनुरोध, दर्ज होने से लेकर पूरा होने तक।',
    'intro_maintenance_index_how' => 'किरायेदार अपने पोर्टल से ये दर्ज कर सकते हैं। ठेकेदार सौंपें, लागत पर नज़र रखें, और काम पूरा होने पर यह व्यय बन सकता है।',
    'intro_maintenance_create_what' => 'जो चीज़ ठीक होनी है उसे दर्ज करें।',
    'intro_maintenance_create_how' => 'तस्वीरें और साफ़ विवरण दूसरी बार जाने से बचाते हैं। प्राथमिकता ईमानदारी से तय करें — सब कुछ अत्यावश्यक हो तो कुछ भी अत्यावश्यक नहीं रहता।',
    'intro_maintenance_view_what' => 'एक अनुरोध: उसका इतिहास, तस्वीरें, किसे सौंपा गया और कितना ख़र्च हुआ।',
    'intro_maintenance_view_how' => 'यहाँ दर्ज लागत को व्यय में बदला जा सकता है, और यही उसे खातों में लाता है।',
    'intro_maintenance_edit_what' => 'रखरखाव अनुरोध का विवरण बदलें।',
    'intro_maintenance_edit_how' => 'स्थिति बदलना ही किरायेदार को बताता है कि कुछ हो रहा है, बशर्ते उसने पोर्टल से अनुरोध किया हो।',
    'intro_maintenance_contractors_what' => 'मरम्मत के लिए जिन लोगों और फ़र्मों को बुलाते हैं।',
    'intro_maintenance_contractors_how' => 'यहाँ काम और दर दर्ज करने से काम सौंपना तेज़ होता है और लागत बढ़ने पर तुलना के लिए कुछ मिलता है।',
    'intro_maintenance_reports_what' => 'रखरखाव पर कितना ख़र्च हो रहा है — संपत्ति, श्रेणी और ठेकेदार के हिसाब से।',
    'intro_maintenance_reports_how' => 'इससे पता चलता है कि कौन-सा भवन ज़रूरत से ज़्यादा ख़र्च करा रहा है, या कौन-सी बार-बार आने वाली ख़राबी ठीक होने के बजाय बस ढकी जा रही है।',
    'intro_utilities_index_what' => 'पानी, बिजली और अन्य सेवाएँ जिनका पैसा किरायेदारों से वसूला जाता है।',
    'intro_utilities_index_how' => 'मीटर रीडिंग दर्ज करें, और आपकी दर से रकम निकलकर उस किरायेदार के बकाया में जुड़ जाती है।',
    'intro_utilities_readings_what' => 'मीटर रीडिंग, और उनसे निकाले गए शुल्क।',
    'intro_utilities_readings_how' => 'मौजूदा रीडिंग डालें; खपत पिछली बार से अंतर है। नई किरायेदारी की पहली रीडिंग ध्यान से जाँचें — उसके बाद का सब कुछ उसी पर टिका है।',
    'intro_utilities_types_what' => 'जिन सेवाओं का बिल बनाते हैं, और हर एक की दर कैसे तय होती है।',
    'intro_utilities_types_how' => 'मीटर वाली आपूर्ति के लिए प्रति-इकाई चुनें, तय मासिक शुल्क के लिए फ़्लैट, और जहाँ खपत के साथ दर बदले वहाँ श्रेणीबद्ध।',
    'intro_vacancies_index_what' => 'जिन खाली इकाइयों का आप विज्ञापन कर रहे हैं, और उन पर आई पूछताछ।',
    'intro_vacancies_index_how' => 'केवल खाली इकाइयाँ ही सूचीबद्ध हो सकती हैं। उस इकाई पर पट्टा बनते ही सूची अपने आप बंद हो जाती है।',
    'intro_vacancies_create_what' => 'किसी खाली इकाई का विज्ञापन करें।',
    'intro_vacancies_create_how' => 'किराया और विवरण इकाई से आते हैं। तस्वीरें जोड़ें — बिना तस्वीर वाली सूची को कहीं कम पूछताछ मिलती है।',
    'intro_vacancies_view_what' => 'एक सूची: वह कैसी पढ़ी जाती है, और किसने उसके बारे में पूछा।',
    'intro_vacancies_view_how' => 'अच्छी लगने वाली पूछताछ को किरायेदार बनाएँ, फिर पट्टा — इससे सूची अपने आप बंद हो जाती है।',
    'intro_vacancies_inquiries_what' => 'जिन लोगों ने किसी खाली इकाई के बारे में पूछा है।',
    'intro_vacancies_inquiries_how' => 'हर एक को संपर्क किया गया या बंद चिह्नित करें ताकि किसी को दो बार न टोका जाए और कोई छूट भी न जाए।',
    'intro_reports_index_what' => 'संचालन की रिपोर्टें — वसूली, अधिभोग और बकाया।',
    'intro_reports_index_how' => 'ये आपके रोज़मर्रा के रिकॉर्ड पढ़ती हैं। खातों के लिए इसके बजाय लेजर के विवरण देखें।',
    'intro_reports_financial_what' => 'एक अवधि में वसूला और ख़र्च किया गया पैसा।',
    'intro_reports_financial_how' => 'यह नकदी को उसकी आवाजाही के समय गिनती है। लेजर वाला लाभ-हानि आय को तब गिनता है जब वह देय हुई, इसलिए दोनों अलग सवालों का जवाब देते हैं।',
    'intro_reports_occupancy_what' => 'आपकी कितनी जगह कमाई कर रही है, और कितनी ख़ाली पड़ी है।',
    'intro_reports_occupancy_how' => 'अधिभोग पट्टे की स्थिति पर चलता है, इसलिए वह उतना ही सही है जितने आपके पट्टे। पट्टा ख़त्म होने के बाद भी भरी हुई चिह्नित इकाई इस आँकड़े को बढ़ा-चढ़ाकर दिखाएगी।',
    'intro_reports_custom_what' => 'अपनी पसंद के कॉलम और फ़िल्टर चुनकर अपनी रिपोर्ट बनाएँ।',
    'intro_reports_custom_how' => 'जिसे दोबारा काम में लेना हो या आगे भेजना हो उसे स्प्रेडशीट में निर्यात करें।',
    'intro_expenses_reports_what' => 'आपने क्या ख़र्च किया, संपत्ति और श्रेणी के हिसाब से।',
    'intro_expenses_reports_how' => 'लागत उसी महीने में गिनी जाती है जिसमें वह बनी, इसलिए देर से चुकाया गया बिल भी सही महीने में ही आता है।',
    'intro_payments_gateway-transactions_what' => 'ऑनलाइन गेटवे से आए भुगतान।',
    'intro_payments_gateway-transactions_how' => 'ये अपने आप दर्ज होते हैं और सीधे बैंक में जाते हैं, क्योंकि नकद किसी के हाथ नहीं आया। यहाँ विफल लेनदेन का मतलब है कि किरायेदार से पैसा लिया ही नहीं गया।',
    'intro_payments_gateway-settings_what' => 'ऑनलाइन भुगतान प्रदाता जोड़ें ताकि किरायेदार ख़ुद भुगतान कर सकें।',
    'intro_payments_gateway-settings_how' => 'घोषणा करने से पहले एक छोटे असली भुगतान से जाँच लें — ग़लत कुंजी किरायेदार के सिरे पर चुपचाप विफल होती है।',
    'intro_payments_gateway-pay_what' => 'ऑनलाइन भुगतान करते समय किरायेदार को दिखने वाला पन्ना।',
    'intro_payments_gateway-pay_how' => 'यह देखने के लिए इसे खोलें कि उन्हें क्या दिखेगा। सफल भुगतान अपने आप दर्ज होकर उनके सबसे पुराने शुल्क चुका देता है।',
    'intro_settings_index_what' => 'कंपनी का विवरण, मुद्रा, मॉड्यूल और पूरे सिस्टम के नियम।',
    'intro_settings_index_how' => 'मॉड्यूल टैब पूरी सुविधाओं को चालू और बंद करता है। कुछ के लिए ऊँची योजना चाहिए, और वे चिह्नित हैं।',
    'intro_settings_reminders_what' => 'अपने आप जाने वाले संदेश जो किरायेदारों को बताते हैं कि क्या देय है और क्या बकाया।',
    'intro_settings_reminders_how' => 'अनुस्मारक वही पढ़ते हैं जो सचमुच बकाया है, इसलिए चुका चुके किरायेदार को कभी नहीं टोका जाता। चालू करने से पहले टेम्पलेट ख़ुद पर आज़माएँ।',
    'intro_settings_backup_what' => 'अपना डेटा निर्यात करें, या किसी दूसरे सिस्टम से लाएँ।',
    'intro_settings_backup_how' => 'कोई भी बड़ा काम करने से पहले निर्यात ले लें — थोक आयात, डेटा की सफ़ाई, या ऐसा बदलाव जिस पर भरोसा न हो।',
    'intro_masters_users_what' => 'कौन लॉगिन कर सकता है, और हर एक को क्या करने की अनुमति है।',
    'intro_masters_users_how' => 'कम से कम दो लोगों को स्वीकृति का अधिकार दें — कोई अपना ही काम स्वीकृत नहीं कर सकता, इसलिए एक ही स्वीकर्ता होने पर कुछ भी कभी स्वीकृत नहीं होगा।',
    'intro_masters_roles_what' => 'अनुमतियों के समूह जो तय करते हैं कि उपयोगकर्ता क्या देख और बदल सकता है।',
    'intro_masters_roles_how' => 'हर भूमिका को उतना ही दें जितना ज़रूरी है। जो देखभाल करने वाला भुगतान मिटा ही नहीं सकता, वह उसे ग़लती से भी नहीं मिटाएगा।',
    // Ledger documentation page (part 36)
    'docs_ledger_guide' => 'लेखा लेजर',
    'docs_led_intro' => 'पूरे सिस्टम के पीछे एक पूर्ण द्वि-प्रविष्टि लेजर काम करता है। किराया, भुगतान, जमा और व्यय अपने आप उसमें दर्ज होते जाते हैं, इसलिए बिना किसी के जर्नल प्रविष्टि लिखे आपके बहीखाते सही बने रहते हैं।',
    'docs_led_intro_note' => 'सिस्टम चलाने के लिए आपको द्वि-प्रविष्टि लेखांकन समझने की ज़रूरत नहीं। भुगतान और व्यय वैसे ही दर्ज करें जैसे हमेशा करते आए हैं; लेजर अपना ध्यान ख़ुद रखता है। यह पन्ना बताता है कि वह क्या कर रहा है, और वे कुछ पन्ने जहाँ वह आपसे कुछ माँगता है।',
    'docs_led_ideas' => 'तीन बातें जो जान लेनी चाहिए',
    'docs_led_accrual' => 'किराया पहले देय होता है, फिर चुकाया जाता है',
    'docs_led_accrual_desc' => 'हर अवधि में चालू हर पट्टे के लिए एक शुल्क बनता है। वही क्षण है जब किराया आय बनता है और जब किरायेदार पर देनदारी चढ़ती है — तब नहीं जब वह पैसा देता है। फिर कोई भुगतान एक या अधिक शुल्क चुकाता है, सबसे पुराने से शुरू करके। इसीलिए बकाया बिल्कुल सटीक रहता है: आंशिक भुगतान देनदारी को ठीक उतना ही घटाता है जितना चुकाया गया, और एक महीने का अतिरिक्त भुगतान अब अगले महीने की कमी नहीं छिपा सकता।',
    'docs_led_float' => 'किसी के हाथ में पड़ी नकदी पर नज़र रहती है',
    'docs_led_float_desc' => 'जब कोई नकद वसूलता है तो वह सीधे बैंक नहीं जाता — वह किसी नकदी पेटी या उसके फ़्लोट में जाता है, यानी कंपनी की ओर से रखा गया पैसा। बैंक में जमा करने पर वह विप्रेषण दर्ज करता है। शेष तभी घटता है जब कोई स्वीकर्ता पुष्टि करे। किसी भी समय आप देख सकते हैं कि क्या और कहाँ रखा है।',
    'docs_led_immutable' => 'दर्ज हो चुकी प्रविष्टियाँ कभी नहीं बदलतीं',
    'docs_led_immutable_desc' => 'एक बार प्रविष्टि दर्ज हो जाने पर उसे न संपादित किया जा सकता है न मिटाया। ग़लती को उलटी प्रविष्टि से सुधारा जाता है, जो मूल को रद्द कर देती है और दोनों रिकॉर्ड में बनी रहती हैं। इसी वजह से पिछले महीने छापा हुआ विवरण आज भी सच है।',
    'docs_led_setup' => 'इसे तैयार करना',
    'docs_led_setup_desc' => 'लेजर कुछ भी दर्ज कर सके, उससे पहले चार काम, एक ही बार:',
    'docs_led_s1' => '1. दो लोगों को स्वीकृति का अधिकार दें',
    'docs_led_s1_desc' => 'सेटिंग्स &rsaquo; उपयोगकर्ता, "भुगतान और जमा स्वीकृत कर सकते हैं" पर निशान लगाएँ। दो लोग अगर चाहते हैं कि पैसा बाहर जाने पर दूसरी नज़र पड़े; एक ही काफ़ी है अगर आप अकेले सिस्टम चलाते हैं और स्व-स्वीकृति चालू रखते हैं।',
    'docs_led_s2' => '2. अपने खाते बनाएँ',
    'docs_led_s2_desc' => 'लेजर &rsaquo; खातों की सूची &rsaquo; नया खाता। हर बैंक खाता जोड़ें (प्रकार: संपत्ति, किस्म: बैंक खाता), कोई भी नकदी पेटी, और वे व्यय खाते जिन पर आप रिपोर्ट चाहते हैं — बिजली, वेतन, मरम्मत।',
    'docs_led_s3' => '3. डिफ़ॉल्ट बैंक जोड़ें',
    'docs_led_s3_desc' => 'लेजर &rsaquo; खाता मानचित्रण। "डिफ़ॉल्ट बैंक खाता" वाली पंक्ति तब तक उजागर रहती है जब तक आप उसे तय न करें। जब तक वह किसी असली खाते पर न लगे, बैंक हस्तांतरण और गेटवे भुगतान दर्ज नहीं हो सकते।',
    'docs_led_s4' => '4. शुल्क बनाने वाली प्रक्रिया निर्धारित करें',
    'docs_led_s4_desc' => 'एक दैनिक क्रॉन हर पट्टे का किराया शुल्क देय होते ही बना देता है। उसे विलंब शुल्क और अनुस्मारक वाली प्रक्रियाओं से पहले चलना चाहिए, क्योंकि वे उन्हीं शुल्कों को पढ़ती हैं। इसके बिना बकाया जमा रह जाता है और किसी को याद नहीं दिलाया जाता।',
    'docs_led_accounts' => 'खातों की सूची',
    'docs_led_accounts_desc' => 'आप जितने चाहें खाते बना सकते हैं। कुछ आपके लिए बना दिए जाते हैं और उन पर सिस्टम का निशान होता है — स्वचालित प्रविष्टियाँ उन्हीं पर टिकी हैं, इसलिए वे मिटाए नहीं जा सकते, हालाँकि उनका नाम बदला जा सकता है।',
    'docs_led_a_asset' => 'संपत्तियाँ',
    'docs_led_a_asset_d' => 'बैंक खाते, नकदी पेटियाँ, फ़्लोट, और जो किरायेदारों पर बकाया है',
    'docs_led_a_liab' => 'देनदारियाँ',
    'docs_led_a_liab_d' => 'किरायेदारों की ओर से रखी गई जमा, और जो आप पर आपूर्तिकर्ताओं का बकाया है',
    'docs_led_a_eq' => 'पूँजी',
    'docs_led_a_eq_d' => 'आरंभिक शेष और संचित लाभ',
    'docs_led_a_inc' => 'आय',
    'docs_led_a_inc_d' => 'किराया, विलंब शुल्क, वसूली गई उपयोगिताएँ, ज़ब्त की गई जमा',
    'docs_led_a_exp' => 'व्यय',
    'docs_led_a_exp_d' => 'जिस पर भी आप पैसा ख़र्च करते हैं; जितने चाहें उतने जोड़ें',
    'docs_led_kind_note' => '"किस्म" वाला ख़ाना सजावट नहीं है — वह तय करता है कि खाता कहाँ दिखेगा। नकद जमा करते समय गंतव्य के रूप में केवल बैंक खाता चिह्नित खाते दिखते हैं, और किसी व्यय का भुगतान करते समय स्रोत केवल बैंक या नकद खाते हो सकते हैं। जो खाता सामान्य छोड़ा गया है वह केवल हाथ से की गई प्रविष्टियों के लिए उपलब्ध रहता है।',
    'docs_led_currency_note' => 'हर खाता एक ही मुद्रा रखता है। USD का बैंक खाता TZS वाले से अलग खाता है, और कोई प्रविष्टि मुद्राएँ मिला नहीं सकती। इसी कारण विवरण भी हर मुद्रा के लिए अलग बनते हैं।',
    'docs_led_float_h' => 'फ़्लोट और विप्रेषण',
    'docs_led_float_h_desc' => 'नकदी दो जगह रहती है। व्यक्तिगत फ़्लोट तब अपने आप बनता है जब कोई पहली बार नकद भुगतान दर्ज करता है, और उसी के नाम पर होता है। साझा नकदी पेटी वह है जो आप स्वयं खातों की सूची में बनाते हैं — किस्म को नकद रखें — और वह किसी एक की नहीं होती। दोनों एक ही तरह बैंक में जाती हैं; फ़र्क़ यह है कि फ़्लोट बता सकता है कि पैसा किसके पास था, साझा पेटी नहीं।',
    'docs_led_f1' => 'कोई वसूलीकर्ता नकद भुगतान दर्ज करता है। उसका फ़्लोट बढ़ता है।',
    'docs_led_f2' => 'वह पैसा बैंक में जमा करता है, फिर लेजर &rsaquo; फ़्लोट खोलकर "नकद बैंक में डालें" पर क्लिक करता है और रकम, गंतव्य खाता तथा जमा पर्ची संख्या भरता है।',
    'docs_led_f3' => 'अभी कुछ नहीं हिलता। फ़्लोट में नकदी अब भी दिखती है।',
    'docs_led_f4' => 'कोई दूसरा व्यक्ति इसे स्वीकृत करता है। तभी फ़्लोट घटता है और बैंक बढ़ता है।',
    'docs_led_f_note' => 'कौन-से तरीक़े किसी के हाथ में नकदी देते हैं, यह लेजर &rsaquo; खाता मानचित्रण में तय होता है। डिफ़ॉल्ट रूप से केवल नकद: चेक बैंक में जमा होता है, रखा नहीं जाता, और हस्तांतरण तथा गेटवे भुगतान किसी के हाथ से गुज़रते ही नहीं।',
    'docs_led_approval' => 'किसे स्वीकृति चाहिए',
    'docs_led_approval_desc' => 'नियम सरल है: जो हुआ उसे दर्ज करना कभी नहीं रोका जाता, पर पैसा बाहर जाने के लिए हमेशा दूसरा व्यक्ति चाहिए।',
    'docs_led_action' => 'कार्य',
    'docs_led_needs' => 'स्वीकृति',
    'docs_led_ap1' => 'भुगतान या जमा दर्ज करना',
    'docs_led_no' => 'नहीं',
    'docs_led_ap2' => 'ऐसा व्यय दर्ज करना जो अभी चुकाया नहीं गया',
    'docs_led_ap3' => 'वसूली गई नकदी बैंक में डालना',
    'docs_led_yes' => 'हाँ',
    'docs_led_ap4' => 'आपूर्तिकर्ता को भुगतान करना',
    'docs_led_ap5' => 'जमा लौटाना या ज़ब्त करना',
    'docs_led_ap6' => 'हाथ से की गई प्रविष्टि या आरंभिक शेष',
    'docs_led_self_note' => 'डिफ़ॉल्ट रूप से एक व्यक्ति अपना ही अनुरोध स्वीकृत कर सकता है, और इसी से अकेला मकान मालिक सिस्टम चला पाता है। लेजर &rsaquo; खाता मानचित्रण में "अपने ही अनुरोध स्वीकृत करने दें" बंद कर दें, तो पैसा बाहर जाने के लिए हमेशा दूसरा व्यक्ति चाहिए — यहाँ का इकलौता नियंत्रण जिसे अकेला उपयोगकर्ता तोड़ नहीं सकता। बंद होने पर और केवल एक स्वीकर्ता होने पर कुछ भी कभी स्वीकृत नहीं होगा।',
    'docs_led_statements' => 'विवरण',
    'docs_led_statements_desc' => 'लेजर &rsaquo; विवरण में तीन दृश्य हैं, सभी हर मुद्रा के लिए अलग:',
    'docs_led_st_pl' => 'लाभ &amp; हानि',
    'docs_led_st_pl_d' => 'एक अवधि की आय और व्यय, जिन्हें एक संपत्ति तक छाना जा सकता है। आय तब गिनी जाती है जब वह देय हुई और व्यय तब जब वह बना, न कि जब नकदी चली।',
    'docs_led_st_bs' => 'तुलन-पत्र',
    'docs_led_st_bs_d' => 'किसी भी तारीख़ पर आपके पास क्या है, आप पर क्या बकाया है और क्या बचता है। प्रतिधारित आय उस तारीख़ तक की सारी आय और व्यय से निकाली जाती है।',
    'docs_led_st_ag' => 'आयु-वार बकायादार',
    'docs_led_st_ag_d' => 'किस पर क्या बकाया है, कितनी देरी हुई इसके अनुसार बँटा हुआ: चालू, 31–60, 61–90 और 90 दिन से अधिक।',
    'docs_led_drill' => 'हर आँकड़ा एक कड़ी है। उस खाते के लेजर तक क्लिक करके जाएँ और चलते शेष के साथ हर हलचल देखें, और वहाँ से उस प्रविष्टि तक जो उसके पीछे है। कोई संख्या ग़लत लगे तो कारण जानने का यही सबसे तेज़ रास्ता है।',
    'docs_led_tb' => 'परीक्षण शेष स्वास्थ्य जाँच है: नामे और जमा बराबर होने चाहिए। हर प्रविष्टि सहेजते समय जाँची जाती है, इसलिए यदि कभी अंतर दिखे तो किसी ने ऐप्लिकेशन के बाहर से डेटाबेस बदला है।',
    'docs_led_closing' => 'अवधि बंद करना',
    'docs_led_closing_desc' => 'जिस महीने की रिपोर्ट बन गई उसे बंद कर दें: लेजर &rsaquo; खाता मानचित्रण &rsaquo; बहीखाते बंद करें, और तारीख़ तय करें। फिर उस तारीख़ या उससे पहले कुछ भी दर्ज नहीं हो सकता — न किसी व्यक्ति से, न API कॉल से, न निर्धारित प्रक्रिया से। फिर से खोलने के लिए तारीख़ हटा दें।',
    'docs_led_faq' => 'आम सवाल',
    'docs_led_q1' => 'सबका बकाया शून्य दिख रहा है।',
    'docs_led_q1_a' => 'शुल्क बनाने वाली प्रक्रिया चली ही नहीं। बकाया बिना चुकाए शुल्कों का जोड़ है, इसलिए जब तक शुल्क न बनें कुछ बकाया ही नहीं। एक बार हाथ से चलाएँ, फिर रोज़ के लिए निर्धारित कर दें।',
    'docs_led_q2' => 'कोई भुगतान लेजर तक नहीं पहुँचा।',
    'docs_led_q2_a' => 'प्रायः डिफ़ॉल्ट बैंक खाता जुड़ा नहीं है, या उस भुगतान की मुद्रा में कोई खाता ही नहीं। भुगतान स्वयं सही दर्ज है — केवल लेजर प्रविष्टि नहीं बनी, और खाता बनते ही वह दर्ज की जा सकती है।',
    'docs_led_q3' => 'फ़्लोट में वह नकदी अब भी दिख रही है जो दिनों पहले बैंक में डाली गई थी।',
    'docs_led_q3_a' => 'विप्रेषण स्वीकृति की प्रतीक्षा में है। फ़्लोट का विवरण खोलें — उसमें वह रकम दिखती है जो घोषित है पर अभी स्वीकृत नहीं, और स्वीकृति के बाद शेष क्या होगा।',
    'docs_led_q4' => 'क्या ग़लती से दर्ज की गई प्रविष्टि संपादित की जा सकती है?',
    'docs_led_q4_a' => 'नहीं, और यह जानबूझकर है। प्रविष्टि खोलें और उलटें पर क्लिक करें। इससे उसे रद्द करती हुई दर्पण प्रविष्टि बनती है, जिसे स्वयं स्वीकृति चाहिए। दोनों रिकॉर्ड में बनी रहती हैं।',
    'docs_led_q5' => 'लेजर चालू करते ही बकाया बदल गया।',
    'docs_led_q5_a' => 'यह अपेक्षित है। पहले बकाया बीते महीनों को किराए से गुणा करके, चुकाई गई सारी रकम घटाकर अनुमानित होता था। अब यह बिना चुकाए शुल्कों का सटीक जोड़ है, इसलिए आंशिक भुगतान और बीच के बदलाव ठीक से दिखते हैं।',
    // Unit profitability (part 37)
    'rep_unit_pl' => 'इकाईवार लाभप्रदता',
    'rep_up_shared' => 'साझा लागत',
