    'rep_up_by_rent' => 'किराए के अनुपात में',
    'rep_up_no_shared' => 'इस अवधि में कोई साझा लागत नहीं',
    'rep_up_income' => 'आय',
    'rep_up_direct' => 'सीधी लागत',
    'rep_up_apportioned' => 'साझा लागत का हिस्सा',
    'rep_up_total_cost' => 'कुल लागत',
    'rep_up_net' => 'शुद्ध',
    'rep_up_margin' => 'मार्जिन',
    'rep_up_unallocated' => 'किसी संपत्ति से नहीं जुड़ी',
    'rep_up_unallocated_help' => 'ये यहाँ दिखाई जाती हैं, इकाइयों पर नहीं डाली जातीं — इसीलिए ऊपर के कुल उसी अवधि के लाभ-हानि से कम हैं।',
    'rep_up_note' => 'जो लागत संपत्ति पर दर्ज है पर किसी इकाई पर नहीं — छत, चौकीदार, पानी की मुख्य लाइन — वह हर इकाई के किराए के अनुपात में बाँटी जाती है। खाली इकाइयाँ भी शामिल हैं और अपना हिस्सा उठाती हैं, इसलिए उनका घाटा ही बताता है कि खाली रहना कितना महँगा है। हिस्सा इकाई के मौजूदा किराए से निकलता है, इसलिए किराया बदलने पर बीती अवधियाँ भी बदल जाती हैं।',
    // Receipt account picker (part 38)
    'rcp_account' => 'किसमें प्राप्त हुआ',
    'rcp_auto' => 'अपने आप तय करें',
    'rcp_help_cash' => 'केवल नकदी पेटियाँ और फ़्लोट — यह पैसा अभी बैंक तक नहीं पहुँचा है।',
    'rcp_help_bank' => 'केवल बैंक खाते।',
    'rcp_help_none' => 'इस मुद्रा में कोई मिलता-जुलता खाता नहीं। यह अपने आप तय हो जाएगा।',
    // Cash and approval policy (part 38)
    'led_cash_policy' => 'नकदी और स्वीकृतियाँ',
    'led_cash_methods' => 'वे तरीक़े जो किसी के हाथ में नकदी देते हैं',
    'led_cash_methods_help' => 'ये नकदी पेटी या फ़्लोट में जाते हैं और बैंक का पैसा तभी गिने जाते हैं जब बैंक में जमा हो जाएँ। बाकी सब सीधे बैंक खाते में दर्ज होता है।',
    'led_self_approve' => 'अपने ही अनुरोध स्वीकृत करने दें',
    'led_self_approve_help' => 'चालू होने पर एक ही व्यक्ति नकदी दर्ज कर सकता है और उसे बैंक में डालने की स्वीकृति भी दे सकता है — अकेले सिस्टम चलाने पर यह ज़रूरी है। बंद होने पर पैसा बाहर जाने के लिए हमेशा दूसरा व्यक्ति चाहिए, और यही यहाँ का इकलौता नियंत्रण है जिसे अकेला उपयोगकर्ता तोड़ नहीं सकता।',
    'led_err_no_cash_method' => 'कम से कम एक तरीक़ा चुनें, वरना कोई कभी नकदी रख ही नहीं सकेगा',
    // Part 38 documentation
    'docs_led_receipt' => 'प्राप्त राशि कहाँ जाए, यह चुनना',
    'docs_led_receipt_desc' => 'भुगतान या जमा दर्ज करते समय "किसमें प्राप्त हुआ" का खाना मिलता है। उसमें क्या दिखेगा यह तरीक़े पर निर्भर है: नकद केवल नकदी पेटी या फ़्लोट में जा सकता है, और हस्तांतरण या चेक केवल बैंक खाते में। यह नुक्ताचीनी नहीं है — नकद को सीधे बैंक खाते में डालना यह दावा करेगा कि पैसा बैंक पहुँच गया जबकि उसे वहाँ कोई ले ही नहीं गया।',
    'docs_led_receipt_auto' => '"अपने आप तय करें" पर छोड़ने से वह हमेशा की तरह चलता है: नकद उसी के फ़्लोट में जाता है जिसने दर्ज किया, और बाकी सब डिफ़ॉल्ट बैंक वाले खाते में। जहाँ-जहाँ सचमुच पैसा रखा जाता है — रिसेप्शन, साइट ऑफ़िस — वहाँ एक-एक नकदी पेटी बनाएँ, तो शेष हर पेटी में रखे पैसे से मेल खाएँगे।',

    // Part 39 — automatic billing start
    'lease_bill_from' => 'इस तारीख से स्वचालित बिलिंग',
    'lease_bill_from_help' => 'शुरुआत की तारीख से किराया बिल करने के लिए खाली छोड़ें। इसे तब भरें जब यह लीज़ इस सिस्टम का उपयोग शुरू करने से पहले शुरू हुई हो: इस तारीख से पहले का किराया बिल नहीं होगा, इसलिए जो भी बकाया है उसे शुरुआती बकाया के रूप में दर्ज करें।',
    'lease_bill_from_edit_help' => 'इस तारीख से पहले का किराया स्वचालित रूप से बिल नहीं होता। इसे पहले की तारीख पर ले जाने से सिस्टम अगली बार पहले की अवधियों का बिल बनाएगा, इसलिए ऐसा तभी करें जब वे कभी बिल न हुई हों या बकाया के रूप में दर्ज न हुई हों।',
    'lease_bill_from_view_help' => 'पहले का किराया इस सिस्टम से पहले, शुरुआती शेष के रूप में बिल किया गया था।',
    'lease_bill_from_invalid' => 'स्वचालित बिलिंग की तारीख मान्य नहीं है',
    'lease_bill_from_after_end' => 'स्वचालित बिलिंग की तारीख समाप्ति तारीख के बाद नहीं हो सकती',

    // Part 40 — opening data import
    'imp_t_rent_roll' => 'किराया सूची (Rent roll)',
    'imp_t_rent_roll_what' => 'हर पंक्ति के लिए संपत्ति, इकाई और किरायेदार बनाता है (यदि वे पहले से नहीं हैं), फिर एक सक्रिय पट्टा, और यदि आप दें तो रखी गई जमा भी।',
    'imp_t_rent_roll_where' => 'संपत्तियाँ, इकाइयाँ (अधिभोगित के रूप में चिह्नित), किरायेदार, पट्टे और जमा। इन पट्टों का स्वचालित किराया बिल गो-लाइव तिथि से शुरू होता है।',
    'imp_t_rent_roll_books' => 'पट्टे खातों में कुछ दर्ज नहीं करते। रखी गई जमा \'किरायेदारों की रखी जमा\' में जुड़ती है, जिसका संतुलन \'प्रारंभिक शेष इक्विटी\' से होता है, और तिथि गो-लाइव से एक दिन पहले की होती है।',
    'imp_t_rent_roll_not' => 'यह दर्ज नहीं करता कि किरायेदारों पर कितना बकाया है — उसके लिए \'प्रारंभिक बकाया\' का उपयोग करें — और यह किरायेदारों को कोई संदेश नहीं भेजता।',
    'imp_c_property_name' => 'नाम से मौजूदा संपत्ति से मिलाया जाता है, या नई बनाई जाती है',
    'imp_c_property_type' => 'residential, commercial, land या mixed. डिफ़ॉल्ट residential',
    'imp_c_unit_number' => 'संपत्ति के भीतर मिलाया जाता है, या नई बनाई जाती है',
    'imp_c_unit_type' => 'apartment, room, shop, office, warehouse, plot, house, flat, hostel या godown. डिफ़ॉल्ट apartment',
    'imp_c_tenant_name' => 'पूरा नाम, पहले खाली स्थान पर विभाजित। या first_name और last_name का उपयोग करें',
